package validations

import (
	"regexp"
	"strconv"

	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// UpdateModuleTTSBody es el cuerpo del PATCH del módulo de texto a voz. El
// handler lo decodifica con `DisallowUnknownFields` (el equivalente del
// `.strict()` de zod: una clave desconocida es un 400) y luego vuelve a
// decodificar el MISMO cuerpo crudo como `map[string]any`, que es lo que el
// repositorio mezcla con `mongo.MergeDeepJSON` por PRESENCIA de clave.
//
// TODOS los campos son punteros: un nil significa «no tocar», y así un `false`,
// un `0` o un `null` explícitos SÍ se aplican. Igual que en el resto de módulos,
// el PATCH NO expone `schema_version` ni `updated_at` —los estampa el
// repositorio en cada escritura— ni `enabled_since`, que es WRITE-ONCE del
// servidor.
type UpdateModuleTTSBody struct {
	Enabled        *bool    `json:"enabled,omitempty"`
	RequireVoice   *bool    `json:"require_voice,omitempty"`
	Language       *string  `json:"language,omitempty"`
	Speed          *float64 `json:"speed,omitempty"`
	SayName        *bool    `json:"say_name,omitempty"`
	MaxChars       *int     `json:"max_chars,omitempty"`
	RepeatedChars  *int     `json:"repeated_chars,omitempty"`
	SkipEmoji      *bool    `json:"skip_emoji,omitempty"`
	RequiredRoleID *string  `json:"required_role_id,omitempty"`
	// El mapa `commands` se mezcla POR CLAVE (`MergeDeepJSON` sin replace), así
	// que un PATCH con un solo subcomando no borra los otros tres. Divergencia
	// deliberada frente a music, que reemplaza el mapa entero desde su `Set()`.
	CommandsGlobal *dbguild.TTSCommandAccess      `json:"commands_global,omitempty"`
	Commands       *map[string]dbguild.TTSCommand `json:"commands,omitempty"`
}

// ttsLanguageRe acepta un código ISO-639-1 con región opcional (`es`, `en`,
// `pt-BR`). El nodo de síntesis usa el código de idioma como selector de timbre,
// así que cualquier cosa fuera de esta forma no es un idioma raro: es un
// documento que hará desaparecer los mensajes en silencio.
var ttsLanguageRe = regexp.MustCompile(`^[a-z]{2}(-[A-Za-z0-9]{2,4})?$`)

// ValidateUpdateModuleTTS comprueba los límites que el merge no puede: el
// repositorio escribe lo que le llega, así que un `speed: 9` o un `max_chars:
// 5000` se guardarían tal cual y el nodo rechazaría cada frase después, ya sin
// nadie mirando. Un puntero nil es «no tocar este campo» y no se valida.
//
// Los techos son los del nodo (`KENA_LINK_TTS_MAX_CHARS`, rango de velocidad),
// no una preferencia: pasarse de ellos no da audio, da rechazo.
func ValidateUpdateModuleTTS(body *UpdateModuleTTSBody) *apierrors.CustomError {
	if body == nil {
		return nil
	}

	if body.Language != nil && !ttsLanguageRe.MatchString(*body.Language) {
		return zodItemError("Invalid language: expected an ISO-639-1 code with an optional region (e.g. `es`, `pt-BR`)", "language")
	}

	if body.Speed != nil {
		if *body.Speed < dbguild.MinTTSSpeed {
			return zodItemError("Too small: expected number to be >="+strconv.FormatFloat(dbguild.MinTTSSpeed, 'g', -1, 64), "speed")
		}
		if *body.Speed > dbguild.MaxTTSSpeed {
			return zodItemError("Too big: expected number to be <="+strconv.FormatFloat(dbguild.MaxTTSSpeed, 'g', -1, 64), "speed")
		}
	}

	if body.MaxChars != nil {
		if *body.MaxChars < 1 {
			return zodItemError("Too small: expected number to be >=1", "max_chars")
		}
		if *body.MaxChars > dbguild.MaxTTSChars {
			return zodItemError("Too big: expected number to be <="+strconv.Itoa(dbguild.MaxTTSChars), "max_chars")
		}
	}

	if body.RepeatedChars != nil {
		if *body.RepeatedChars < 0 {
			return zodItemError("Too small: expected number to be >=0", "repeated_chars")
		}
		if *body.RepeatedChars > dbguild.MaxTTSRepeatedChars {
			return zodItemError("Too big: expected number to be <="+strconv.Itoa(dbguild.MaxTTSRepeatedChars), "repeated_chars")
		}
	}

	// Los dos nullables de primer nivel. `null` (puntero nil) es «quitar el
	// canal / no exigir rol» y es legítimo; la cadena vacía llega del formulario
	// del dashboard cuando el selector se deja sin elegir y significa lo mismo.
	// Lo que no puede pasar es un id que no sea un snowflake.
	for _, f := range []struct {
		value    *string
		property string
	}{
		{body.RequiredRoleID, "required_role_id"},
	} {
		if f.value == nil || *f.value == "" {
			continue
		}
		if !snowflakeRe.MatchString(*f.value) {
			return zodItemError("Invalid snowflake: expected a 17-20 digit id", f.property)
		}
	}

	return nil
}

//	text_only    text                   progression_text
//	voice_only   voice                  progression_voice
//	unified      text y voice           progression_text (nivel = text_xp + voice_xp)
//	separate     text y voice           progression_text / progression_voice
//
// ⚠️ En `unified` la progresión activa es `progression_text` — deliberado
// (ver el comentario de `LevelingProgression`). En TS esta tabla la resuelven
// `resolveLevelingScope`/`levelingProgressionFor` — bot y dashboard las
// consumen en vez de reimplementar el switch; este vertical Mongo no
// necesita resolverla, sólo persiste el documento. Cambiar de modo nunca
// destruye datos: ningún camino de escritura borra ni sobrescribe el bloque
// que el modo activo no usa.
type LevelingXPMode string

const (
	LevelingXPModeTextOnly  LevelingXPMode = "text_only"
	LevelingXPModeVoiceOnly LevelingXPMode = "voice_only"
	LevelingXPModeUnified   LevelingXPMode = "unified"
	LevelingXPModeSeparate  LevelingXPMode = "separate"
)

// LevelingCommandMode espeja `LevelingCommandMode` — mismo patrón que
// `TempvoiceCommandMode`: cómo se pueden invocar los comandos del módulo
// (`rank`, `xp`, `top`).
type LevelingCommandMode string

const (
	LevelingCommandModeSlash  LevelingCommandMode = "slash"
	LevelingCommandModePrefix LevelingCommandMode = "prefix"
	LevelingCommandModeBoth   LevelingCommandMode = "both"
)

// LevelingAnnounceTarget espeja `LevelingAnnounceTarget` — dónde se publica
// el anuncio de subida de nivel.
type LevelingAnnounceTarget string

const (
	LevelingAnnounceTargetCurrent LevelingAnnounceTarget = "current"
	LevelingAnnounceTargetChannel LevelingAnnounceTarget = "channel"
	LevelingAnnounceTargetDM      LevelingAnnounceTarget = "dm"
)

// LevelingRewardStacking espeja `LevelingRewardStacking` — qué pasa con los
// roles de recompensa anteriores al subir de nivel: `stack` los conserva
// todos, `replace` quita el del nivel previo.
type LevelingRewardStacking string

const (
	LevelingRewardStackingStack   LevelingRewardStacking = "stack"
	LevelingRewardStackingReplace LevelingRewardStacking = "replace"
)

// LevelingCardMode espeja `LevelingCardMode` — mismo par que
// `GreeterImageMode`: `basic` es la tarjeta de fábrica (fondo + acento),
// `advanced` es el lienzo del editor.
type LevelingCardMode string

const (
	LevelingCardBasic    LevelingCardMode = "basic"
	LevelingCardAdvanced LevelingCardMode = "advanced"
)

// LevelingAccessMode espeja `DBAccessMode` (`"only" | "all_except"`): `only`
// es lista blanca, `all_except` lista negra.
type LevelingAccessMode string

const (
	LevelingAccessOnly      LevelingAccessMode = "only"
	LevelingAccessAllExcept LevelingAccessMode = "all_except"
)

// LevelingMultiplier mirrors `DBLevelingMultiplier` — multiplicador de XP
// atado a un rol o a un canal, según la lista en la que viva.
type LevelingMultiplier struct {
	ID         string  `bson:"id"         json:"id"`
	Multiplier float64 `bson:"multiplier" json:"multiplier"`
}

// LevelingReward mirrors `DBLevelingReward` — al alcanzar `Level` se
// conceden estos roles.
type LevelingReward struct {
	Level   int      `bson:"level"    json:"level"`
	RoleIDs []string `bson:"role_ids" json:"role_ids"`
}

// LevelingVoiceRules mirrors el objeto inline `DBLevelingSource.voice_rules`
// de la interfaz TS — cuándo NO cuenta el tiempo en voz.
type LevelingVoiceRules struct {
	IgnoreAlone    bool `bson:"ignore_alone"    json:"ignore_alone"`
	IgnoreMuted    bool `bson:"ignore_muted"    json:"ignore_muted"`
	IgnoreDeafened bool `bson:"ignore_deafened" json:"ignore_deafened"`
}

// LevelingRequirements mirrors `DBLevelingRequirements` — requisitos de
// elegibilidad que un miembro debe cumplir para ganar XP de UNA fuente
// (texto o voz — cada fuente lleva su PROPIA copia dentro de
// `LevelingSource`, no es un único bloque compartido). Todos con
// "0 / false / lista vacía = sin requisito", así que un guild que no los
// toque no nota ningún cambio: el bloque entero es opt-in.
// `MinMembershipSeconds`/`MinAccountAgeSeconds` aplican en las dos fuentes;
// el resto de campos (salvo `BypassRoleIDs`) SOLO se evalúan en texto — en
// voz no hay mensaje que medir.
type LevelingRequirements struct {
	MinMembershipSeconds     int      `bson:"min_membership_seconds"       json:"min_membership_seconds"`
	MinAccountAgeSeconds     int      `bson:"min_account_age_seconds"      json:"min_account_age_seconds"`
	MinMessageLength         int      `bson:"min_message_length"           json:"min_message_length"`
	IgnoreLinkOnly           bool     `bson:"ignore_link_only"             json:"ignore_link_only"`
	IgnoreAttachmentOnly     bool     `bson:"ignore_attachment_only"       json:"ignore_attachment_only"`
	IgnoreStickerOrEmojiOnly bool     `bson:"ignore_sticker_or_emoji_only" json:"ignore_sticker_or_emoji_only"`
	IgnoreCommands           bool     `bson:"ignore_commands"              json:"ignore_commands"`
	BypassRoleIDs            []string `bson:"bypass_role_ids"              json:"bypass_role_ids"`
}

// LevelingVoiceMetric espeja `LevelingVoiceMetric` — qué magnitud mide la
// progresión de VOZ: "xp" es una tirada de puntos por tick, como el texto;
// "time" hace que el nivel salga directamente de los MINUTOS conectado
// (`floor(voice_seconds / 60)`), sin conceder XP (§1 del contrato v4).
// Sólo válido con XPMode "separate"/"voice_only": en "unified" el nivel es
// la SUMA de texto y voz, y no se pueden sumar minutos con puntos — el bot
// fuerza "xp" ahí con el helper resolveVoiceMetric de `@kena/shared`, este
// vertical Mongo persiste el valor de configuración tal cual.
type LevelingVoiceMetric string

const (
	LevelingVoiceMetricXP   LevelingVoiceMetric = "xp"
	LevelingVoiceMetricTime LevelingVoiceMetric = "time"
)

// LevelingSource mirrors `DBLevelingSource` — reglas de concesión de XP de
// UNA fuente (texto o voz): tasa, requisitos de elegibilidad, exclusiones y
// multiplicadores. Los CUATRO modos de `LevelingXPMode` persisten SIEMPRE
// los dos bloques (`ModuleLeveling.Text`/`.Voice`) — el modo decide cuáles
// CONCEDEN XP, no cuáles existen (ver la tabla de resolución en el
// comentario de `LevelingXPMode`).
//
// `IntervalSeconds` significa cosas distintas en cada fuente y por eso NO se
// llama `Cooldown`:
//   - texto: ventana antispam; sólo el primer mensaje de la ventana da XP.
//   - voz: duración del tick; cada tick completo en voz concede una tirada.
type LevelingSource struct {
	// Metric sólo es relevante en la fuente de VOZ; en texto se IGNORA
	// (siempre "xp") y se persiste por simetría de forma, igual que
	// VoiceRules más abajo. Con "time" esta fuente NO concede XP (Min/Max/
	// la tirada dejan de aplicar): el nivel sale de `voice_seconds`
	// acumulados en Postgres, convertidos a MINUTOS (§1 del contrato v4).
	Metric          LevelingVoiceMetric  `bson:"metric"               json:"metric"`
	Min             int                  `bson:"min"                  json:"min"`
	Max             int                  `bson:"max"                  json:"max"`
	IntervalSeconds int                  `bson:"interval_seconds"     json:"interval_seconds"`
	Requirements    LevelingRequirements `bson:"requirements"         json:"requirements"`
	// ExcludedChannelIDs: canales donde no se gana XP con esta fuente.
	ExcludedChannelIDs []string `bson:"excluded_channel_ids" json:"excluded_channel_ids"`
	// ExcludedRoleIDs: quien tenga uno de estos roles no gana XP con esta fuente.
	ExcludedRoleIDs    []string             `bson:"excluded_role_ids"    json:"excluded_role_ids"`
	RoleMultipliers    []LevelingMultiplier `bson:"role_multipliers"     json:"role_multipliers"`
	ChannelMultipliers []LevelingMultiplier `bson:"channel_multipliers"  json:"channel_multipliers"`
	// VoiceRules sólo se aplica a la fuente de voz; en el bloque de texto se
	// IGNORA. Se persiste igual en los dos bloques por simetría de forma (y
	// para que configurarlo en `Voice` y luego cambiar de modo no pierda
	// nada).
	VoiceRules LevelingVoiceRules `bson:"voice_rules" json:"voice_rules"`
}

// LevelingRewards mirrors el objeto inline `DBLevelingProgression.rewards`
// de la interfaz TS.
type LevelingRewards struct {
	Enabled  bool                   `bson:"enabled"  json:"enabled"`
	Stacking LevelingRewardStacking `bson:"stacking" json:"stacking"`
	Levels   []LevelingReward       `bson:"levels"   json:"levels"`
}

// LevelingAnnounce mirrors el objeto inline `DBLevelingProgression.announce`
// de la interfaz TS. `Content` es un CENTINELA (ver `NewModuleLeveling` en
// el paquete `mocks`): mientras el guild lo tenga byte a byte igual al
// default de fábrica, bot y dashboard lo traducen con la clave i18n
// `announceDefault` — igual que `DEFAULT_TEMPVOICE_PANEL`.
type LevelingAnnounce struct {
	Enabled            bool                   `bson:"enabled"              json:"enabled"`
	Target             LevelingAnnounceTarget `bson:"target"               json:"target"`
	ChannelID          *string                `bson:"channel_id"           json:"channel_id"`
	Content            string                 `bson:"content"              json:"content"`
	DeleteAfterSeconds *int                   `bson:"delete_after_seconds" json:"delete_after_seconds"`
}

// LevelingCurveMode espeja `LevelingCurveMode` — cómo `LevelingProgression`
// deriva el nivel: "formula" usa la curva automática (CurveMultiplier);
// "manual" usa la tabla de umbrales (ManualThresholds). Default "formula"
// (§2 del contrato v4). TIPO PROPIO, no el de dbleveling.CurveMode: este
// paquete (config de Mongo) y dbleveling (descriptor de cómputo Postgres)
// son verticales autocontenidas por diseño — ver el comentario de
// dbleveling.Curve.
type LevelingCurveMode string

const (
	LevelingCurveModeFormula LevelingCurveMode = "formula"
	LevelingCurveModeManual  LevelingCurveMode = "manual"
)

// LevelingProgression mirrors `DBLevelingProgression` — curva, recompensas y
// anuncio de UNA progresión (un nivel). El número de progresiones ACTIVAS lo
// decide `ModuleLeveling.XPMode`: una sola en
// `text_only`/`voice_only`/`unified`, dos (`ProgressionText` +
// `ProgressionVoice`) en `separate`. Los cuatro modos persisten SIEMPRE los
// dos bloques.
//
// ⚠️ En `unified` la progresión activa es `ProgressionText` — deliberado:
// evita un tercer bloque que sólo existiría para ese modo y hace que pasar
// de `unified` a `separate` conserve la curva y las recompensas ya
// configuradas (la de voz arranca con sus propios defaults).
type LevelingProgression struct {
	// CurveMode: "formula" usa la curva automática (CurveMultiplier);
	// "manual" usa la tabla de umbrales (ManualThresholds).
	CurveMode LevelingCurveMode `bson:"curve_mode" json:"curve_mode"`
	// CurveMultiplier: factor de dificultad de la curva `formula`. Rango [0.01, 100].
	CurveMultiplier float64 `bson:"curve_multiplier" json:"curve_multiplier"`
	// ManualThresholds: umbrales ACUMULADOS de la curva `manual`, en orden
	// ascendente — índice 0 es el coste del nivel 1, índice 1 el del nivel
	// 2, etc., en XP o en MINUTOS si la progresión mide tiempo (según el
	// `Metric` de la fuente asociada, §1). Al superar el último umbral no
	// hay más niveles: el miembro se queda en el máximo definido y sigue
	// acumulando XP/minutos sin subir (§2 del contrato v4). Lista vacía =
	// nadie pasa del nivel 0, estado válido a medio configurar. Monotonía
	// estricta y tope de 500 niveles: validación de DASHBOARD, NO enforced
	// aquí (mismo criterio que el rango de CurveMultiplier).
	ManualThresholds []int64          `bson:"manual_thresholds" json:"manual_thresholds"`
	Rewards          LevelingRewards  `bson:"rewards"           json:"rewards"`
	Announce         LevelingAnnounce `bson:"announce"          json:"announce"`
}

// LevelingRankCard mirrors el objeto inline `ModuleLeveling.rank_card` de la
// interfaz TS. `Canvas` reutiliza `GreeterImageCanvas` tal cual — mismo
// lienzo que greeter, incluida la capa `bar` (ver el comentario de
// `GreeterImageElement.BarToken`).
type LevelingRankCard struct {
	Mode          LevelingCardMode   `bson:"mode"           json:"mode"`
	BackgroundURL *string            `bson:"background_url" json:"background_url"`
	AccentColor   string             `bson:"accent_color"   json:"accent_color"`
	Canvas        GreeterImageCanvas `bson:"canvas"         json:"canvas"`
}

// LevelingAccessList mirrors `DBAccessList` — la lista de acceso de un eje
// (roles/canales/categorías) de un comando del módulo.
type LevelingAccessList struct {
	Mode LevelingAccessMode `bson:"mode" json:"mode"`
	IDs  []string           `bson:"ids"  json:"ids"`
}

// LevelingCommandAccess mirrors `DBCommandAccess` — acceso por eje (quién:
// roles, dónde: canales/categorías) de un comando del módulo, o del acceso
// GLOBAL (`ModuleLeveling.CommandsGlobal`).
type LevelingCommandAccess struct {
	Roles      LevelingAccessList `bson:"roles"      json:"roles"`
	Channels   LevelingAccessList `bson:"channels"   json:"channels"`
	Categories LevelingAccessList `bson:"categories" json:"categories"`
}

// LevelingCommandSync mirrors el objeto inline `DBLevelingCommand.use_global`
// de la interfaz TS — herencia POR EJE del acceso global. Un eje en `true`
// lee de `commands_global`; en `false`, del `access` propio del comando.
// A diferencia de tempvoice/music, aquí no hace falta `UnmarshalJSON` para

