		CountAsWarn:    false,
		MaxMessages:    5,
		WindowMs:       5000,
		PurgeBurst:     true,
	}
}

// DefaultAutomodDuplicatesRule — apagada: 3 repeticiones en 30 s.
func DefaultAutomodDuplicatesRule() AutomodDuplicatesRule {
	return AutomodDuplicatesRule{
		Enabled:        false,
		Action:         AutomodActionDelete,
		TimeoutMs:      AutomodDefaultTimeoutMs,
		ExemptRoles:    []string{},
		ExemptChannels: []string{},
		CountAsWarn:    false,
		MaxRepeats:     3,
		WindowMs:       30000,
	}
}

// DefaultAutomodCapsRule — apagada: se evalúan mensajes de 10+ caracteres y se
// permite hasta un 70 % de mayúsculas.
func DefaultAutomodCapsRule() AutomodCapsRule {
	return AutomodCapsRule{
		Enabled:        false,
		Action:         AutomodActionDelete,
		TimeoutMs:      AutomodDefaultTimeoutMs,
		ExemptRoles:    []string{},
		ExemptChannels: []string{},
		CountAsWarn:    false,
		MinLength:      10,
		MaxPercent:     70,
	}
}

// DefaultAutomodLinksRule — apagada y en modo blacklist (`block_all` false) con
// las dos listas vacías: activarla sin tocar nada más no bloquea ningún enlace.
func DefaultAutomodLinksRule() AutomodLinksRule {
	return AutomodLinksRule{
		Enabled:        false,
		Action:         AutomodActionDelete,
		TimeoutMs:      AutomodDefaultTimeoutMs,
		ExemptRoles:    []string{},
		ExemptChannels: []string{},
		CountAsWarn:    false,
		BlockAll:       false,
		AllowedDomains: []string{},
		BlockedDomains: []string{},
	}
}

// DefaultAutomodEmojisRule — apagada: hasta 10 emojis por mensaje.
func DefaultAutomodEmojisRule() AutomodEmojisRule {
	return AutomodEmojisRule{
		Enabled:        false,
		Action:         AutomodActionDelete,
		TimeoutMs:      AutomodDefaultTimeoutMs,
		ExemptRoles:    []string{},
		ExemptChannels: []string{},
		CountAsWarn:    false,
		MaxEmojis:      10,
	}
}

// DefaultAutomodAttachmentsRule — apagada: sin tope de adjuntos (`0`) y sin
// extensiones prohibidas.
func DefaultAutomodAttachmentsRule() AutomodAttachmentsRule {
	return AutomodAttachmentsRule{
		Enabled:           false,
		Action:            AutomodActionDelete,
		TimeoutMs:         AutomodDefaultTimeoutMs,
		ExemptRoles:       []string{},
		ExemptChannels:    []string{},
		CountAsWarn:       false,
		MaxAttachments:    0,
		BlockedExtensions: []string{},
	}
}

// DefaultModerationAutomod — las nueve reglas apagadas (opt-in desde la
// dashboard) y sin exenciones. Al activar una regla sólo borra el mensaje
// (`delete`); escalar a aviso o mute es otra decisión aparte.
func DefaultModerationAutomod() ModerationAutomod {
	return ModerationAutomod{
		Mentions:    DefaultAutomodMentionsRule(),
		Words:       DefaultAutomodWordsRule(),
		Invites:     DefaultAutomodInvitesRule(),
		Spam:        DefaultAutomodSpamRule(),
		Duplicates:  DefaultAutomodDuplicatesRule(),
		Caps:        DefaultAutomodCapsRule(),
		Links:       DefaultAutomodLinksRule(),
		Emojis:      DefaultAutomodEmojisRule(),
		Attachments: DefaultAutomodAttachmentsRule(),
	}
}

// DefaultModerationProtection — el ÚNICO bloque del v3 que nace ACTIVO: es la
// red de seguridad y no cambia nada salvo impedir abusos (jerarquía respetada,
// admins y bots protegidos, sin auto-sanción). Las listas de inmunidad nacen
// vacías.
func DefaultModerationProtection() ModerationProtection {
	return ModerationProtection{
		ImmuneRoles:          []string{},
		ImmuneUsers:          []string{},
		RespectHierarchy:     true,
		HierarchyBypassRoles: []string{},
		ProtectAdmins:        true,
		ProtectBots:          true,
		AllowSelfSanction:    false,
	}
}

// DefaultModerationEscalation — apagado, ventana de 30 días, contando sólo los
// avisos (incluidos los de automod) y reiniciando el contador al disparar un
// peldaño. Sin peldaños: hay que definirlos desde la dashboard.
func DefaultModerationEscalation() ModerationEscalation {
	return ModerationEscalation{
		Enabled:           false,
		WindowMs:          30 * 24 * 60 * 60 * 1000,
		CountTypes:        []InfractionCountableType{InfractionCountableWarn},
		CountAutomod:      true,
		ResetAfterTrigger: true,
		Rules:             []ModerationEscalationRule{},
	}
}

// DefaultModerationEffects — ningún efecto se aplica solo (`never`) salvo el
// borrado al banear, que se PREGUNTA al moderador (`ask`) con la opción
// desmarcada. Las ventanas de purga quedan puestas por si se activan: 1 día en
// el ban, 1 hora en el kick.
func DefaultModerationEffects() ModerationEffects {
	return ModerationEffects{
		VoiceDisconnectOnMute: ModerationEffect{Policy: ModerationEffectNever, Default: false},
		ServerMuteOnMute:      ModerationEffect{Policy: ModerationEffectNever, Default: false},
		StripRolesOnMute:      ModerationEffect{Policy: ModerationEffectNever, Default: false},
		PurgeOnBan:            ModerationEffect{Policy: ModerationEffectAsk, Default: false},
		PurgeOnBanSeconds:     86400,
		PurgeOnKick:           ModerationEffect{Policy: ModerationEffectNever, Default: false},
		PurgeOnKickSeconds:    3600,
		DeleteInvocation:      false,
		EphemeralReplies:      false,
	}
}

// DefaultModerationRaid — apagado: 10 entradas en 10 s disparan el modo raid,
// que sólo AVISA durante 10 minutos. Los avisos van al canal de mod-log
// (`nil`) y sin mención de rol.
func DefaultModerationRaid() ModerationRaid {
	return ModerationRaid{
		Enabled:            false,
		JoinThreshold:      10,
		JoinWindowMs:       10000,
		Action:             ModerationRaidAlert,
		DurationMs:         600000,
		AlertChannelID:     nil,
		AlertRoleID:        nil,
		LockdownChannels:   []string{},
		QuarantineNewJoins: false,
	}
}

// DefaultModerationGate — apagado y sin criterios puestos (edad mínima 0, sin
// avatar obligatorio, sin patrones): activarlo tal cual no rechaza a nadie. La
// acción es sólo avisar, y los bots quedan exentos.
func DefaultModerationGate() ModerationGate {
	return ModerationGate{
		Enabled:             false,
		MinAccountAgeMs:     0,
		RequireAvatar:       false,
		BlockedNamePatterns: []string{},
		Action:              ModerationGateAlert,
		DurationMs:          0,
		ExemptBots:          true,
		AlertChannelID:      nil,
	}
}

// DefaultModerationNukeLimits siembra las 13 acciones vigiladas, todas
// APAGADAS, con castigo heredado y ventana de 1 minuto. Los topes son los
// sensatos para cada familia: 3 para lo destructivo (borrados, bans, kicks,
// prunes, webhooks), 5 para lo creativo/editable (crear canales y roles,
// editarlos, tocar roles de miembros) y 2 para tocar el propio servidor.
func DefaultModerationNukeLimits() map[string]ModerationNukeLimit {
	maxByAction := map[ModerationNukeAction]int{
		ModerationNukeChannelDelete:    3,
		ModerationNukeChannelCreate:    5,
		ModerationNukeChannelUpdate:    5,
		ModerationNukeRoleDelete:       3,
		ModerationNukeRoleCreate:       5,
		ModerationNukeRoleUpdate:       5,
		ModerationNukeMemberBan:        3,
		ModerationNukeMemberKick:       3,
		ModerationNukeMemberPrune:      3,
		ModerationNukeMemberRoleUpdate: 5,
		ModerationNukeWebhookCreate:    3,
		ModerationNukeEmojiDelete:      3,
		ModerationNukeGuildUpdate:      2,
	}
	out := make(map[string]ModerationNukeLimit, len(ModerationNukeActionNames))
	for _, action := range ModerationNukeActionNames {
		out[string(action)] = ModerationNukeLimit{
			Enabled:    false,
			Max:        maxByAction[action],
			WindowMs:   60000,
			Punishment: ModerationNukePunishInherit,
		}
	}
	return out
}

// DefaultModerationAntinuke — apagado. El castigo global por defecto es quitar
// todos los roles (lo menos destructivo que de verdad frena a alguien), se
// vigila también a los bots, y los avisos van al canal de mod-log.
func DefaultModerationAntinuke() ModerationAntinuke {
	return ModerationAntinuke{
		Enabled:        false,
		Punishment:     ModerationNukePunishStripRoles,
		TrustedUsers:   []string{},
		TrustedRoles:   []string{},
		WatchBots:      true,
		AlertChannelID: nil,
		AlertRoleID:    nil,
		Limits:         DefaultModerationNukeLimits(),
	}
}

// DefaultModerationLockdown — mensajes vacíos (el módulo usa su texto por
// defecto), sin roles que se salten el bloqueo y sin lista de canales (el
// bloqueo de servidor alcanza a todos los de texto).
func DefaultModerationLockdown() ModerationLockdown {
	return ModerationLockdown{
		LockMessage:    "",
		UnlockMessage:  "",
		BypassRoles:    []string{},
		ServerChannels: []string{},
	}
}

// ── Normalización ───────────────────────────────────────────────────────────

// NormalizeModeration backfills every collection field that decoded as `nil`
// (from a partial Mongo doc or a legacy cache entry) with a non-nil empty
// value, mirroring the zod `.default([])` / `.default({})`. This keeps the JSON
// body emitting `[]` / `{}` instead of `null` — the exact shape the Node
// service produces after re-parsing through `moduleModerationSchema`.
//
// Scalars and nullable pointers are left untouched: a stored `null` stays
// `null`, matching the `string | null` fields (`log_channel_id`, `mute.role_id`,
// each command's `dm_embed.color`, los `alert_*` del v3). Idempotent.
//
// OJO: normalizar NO es migrar. Aquí sólo se rellenan colecciones vacías; los
// defaults NO-cero del v3 (`timeout_ms`, ventanas, umbrales) los pone
// `MigrateModerationRaw`.
func NormalizeModeration(m *ModuleModeration) {
	if m == nil {
		return
	}

	normalizeModerationAccess(&m.CommandsGlobal)

	if m.Commands == nil {
		m.Commands = map[string]ModerationCommand{}
	} else {
		for k, v := range m.Commands {
			normalizeModerationAccess(&v.Access)
			v.Aliases = ensureModerationStrSlice(v.Aliases)
			m.Commands[k] = v
		}

